import traceback, os

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    parts = []
    parts.append(f"{type(e).__name__}: {e}")
    tb = e.__traceback__
    stack = traceback.extract_tb(tb)
    if len(stack) > max_level:
        stack = stack[-max_level:]
    for frame in stack:
        filename = frame.filename
        parts.append(f"  File \"{cls._truncate_path(filename, max_path_level)}\", line {frame.lineno}, in {frame.name}")
        if frame.line:
            parts.append(f"    {frame.line.strip()}")
    # handle cause
    cause = e.__cause__
    if cause:
        parts.append("Caused by:")
        parts.append(cls.extostr(cause, max_level, max_path_level))
    context = e.__context__
    if context and not e.__suppress_context__:
        parts.append("During handling of the above exception, another exception occurred:")
        parts.append(cls.extostr(context, max_level, max_path_level))
    return "\n".join(parts)

@staticmethod
def _truncate_path(path, max_level):
    parts = path.split(os.sep)
    if len(parts) > max_level:
        return os.sep.join(['...'] + parts[-max_level:])
